/**
 * Shared hosted-command hints. The CLI drives only architecture v2. The one
 * exception is an exit ramp: `deployment`, `stop`, and `delete` still reach a
 * v1 deployment after the v2 call answers 404, so its owner can see, stop, or
 * remove it. Every other command points v1 users at `migrate`.
 */
import { CLI_COMMAND_NAME as CLI } from "./distribution.js";
/**
 * How a v1 deployment moves to v2. A v2 deploy to the same slug replaces the
 * v1 deployment and copies its secrets server-side.
 */
export const V1_MIGRATE_HINT = `Run \`${CLI} migrate\`, then \`${CLI} deploy\`. A v2 deploy to the same slug replaces the v1 deployment.`;
/** Usage error for a local command that got `--prod`. */
export function prodNotSupportedMessage(command) {
    return (`${command} does not support --prod. For a hosted deployment, run ` +
        `\`${CLI} session create --message "…" --wait\`, then \`${CLI} session get <ses_> --prod --slug <slug>\`.`);
}
/** `session create` returns a delivery; read the session after it is allocated. */
export function v2HostedVerifyHint(slug = "<slug>") {
    return (`\`${CLI} session create\` returns a delivery; the session comes later. ` +
        `Pass --wait to wait for it, then ` +
        `\`${CLI} session get <ses_> --prod --slug ${slug}\`.`);
}
